offer:
const salary = num(prefix + "Salary");
        const allowance = num(prefix + "Allowance");
        const awsMonths = num(prefix + "Aws");
        const bonusMonths = num(prefix + "Bonus");
        const benefits = num(prefix + "Benefits");
        const weeklyHours = clamp(num(prefix + "Hours"), 1, 100);
        const commuteDays = clamp(num(prefix + "CommuteDays"), 0, 7);
        const commuteMinutes = clamp(num(prefix + "Commute"), 0, 600);
        const leaveDays = clamp(num(prefix + "Leave"), 0, 60);
        const monthlyCost = num(prefix + "Cost");

        const monthlyOrdinaryCash = salary + allowance;
        const annualBaseCash = monthlyOrdinaryCash * 12;
        const additionalCash = salary * (awsMonths + bonusMonths);
        const annualCash = annualBaseCash + additionalCash;

        let employeeCpf = 0;
        let employerCpf = 0;
        let cpfApplicableWages = 0;

        if ($("cpfStatus").value === "full") {
          const rates = CPF_RATES[$("ageGroup").value];
          const annualOwSubject = Math.min(monthlyOrdinaryCash, OW_MONTHLY_CEILING) * 12;
          const awCeiling = Math.max(0, TOTAL_WAGE_CEILING - annualOwSubject);
          const awSubject = Math.min(additionalCash, awCeiling);
          cpfApplicableWages = annualOwSubject + awSubject;
          employeeCpf = cpfApplicableWages * rates.employee;
          employerCpf = cpfApplicableWages * rates.employer;
        }

        const annualWorkCost = monthlyCost * 12;
        const cashAfterCpfAndCosts = annualCash - employeeCpf - annualWorkCost;
        const paidLeaveWeeks = leaveDays / WORK_DAYS_PER_WEEK;
        const activeWorkWeeks = clamp(52 - paidLeaveWeeks, 1, 52);
        const annualWorkHours = weeklyHours * activeWorkWeeks;
        const annualCommuteHours = commuteDays * (commuteMinutes / 60) * activeWorkWeeks;
        const annualTimeHours = annualWorkHours + annualCommuteHours;
        const effectiveHourly = annualTimeHours > 0
          ? (cashAfterCpfAndCosts + benefits) / annualTimeHours
          : 0;
        const employerPackage = annualCash + employerCpf + benefits;

        return {
          name: offerName(prefix),
          annualCash,
          employeeCpf,
          employerCpf,
          cpfApplicableWages,
          annualWorkCost,
          cashAfterCpfAndCosts,
          benefits,
          employerPackage,
          annualTimeHours,
          effectiveHourly,
          leaveDays,
          weeklyHours
        };
      }
